import json
from pathlib import Path
base=Path(__file__).parent
products={p['id']:p for p in json.loads((base/'input-5.json').read_text())}
out=[]
def lang(name,tagline,description,benefits,textureTitle,textureText,fitText,steps,notes,ingredients,faq):
 return dict(name=name,tagline=tagline,description=description,benefits=benefits,textureTitle=textureTitle,textureText=textureText,fitText=fitText,steps=[dict(title=a,text=b) for a,b in steps],notes=notes,ingredients=ingredients,faq=[dict(question=a,answer=b) for a,b in faq])
def add(id,ar,en,sources,status='exact',research=[]):
 p=products[id];out.append(dict(id=id,brand=p['brand'],productName=p['name'],ar=ar,en=en,sources=[dict(url=u,title=t) for u,t in sources],sourceStatus=status,researchNotes=research,extraImages=[],usageBrief=' '.join(x['text'] for x in en['steps'])))
add('TS0060',lang('بوستر الريتينال فيتا إيه من سيليماكس','خطوة مسائية، بتدرّج يناسب بشرتكِ.','بوستر موضعي بالريتينال للعناية بمظهر الخطوط والملمس؛ كمية صغيرة تُضاف إلى روتين مسائي متدرّج.', ['تحسين مظهر الملمس','عناية بمظهر الخطوط','تطبيق موضعي بكمية قليلة'],'بوستر مركّز للمساء','يُوزّع بكمية صغيرة على المواضع المطلوبة، ثم يُتبع بالترطيب.','لمن اعتادت الريتينويدات أو تستطيع إدخالها تدريجيًا؛ ليس خطوة لتكديس المقشرات.', [('ابدئي بالتدرّج','استخدميه ليلة بعد ليلة أول أسبوعين وفق التحمل.'),('كمية صغيرة','وزّعي قليلًا على المناطق المستهدفة بعيدًا عن العين والشفاه.'),('ترطيب وحماية','أتبعيه بمرطب، واستخدمي واقي الشمس صباحًا.')],'قد يسبب تهيجًا؛ خففي التكرار عند الحاجة. تُتجنب الريتينويدات أثناء الحمل والتخطيط له.', ['ريتينال','تركيبة A-Shot'],[('هل يُستخدم صباحًا؟','اجعليه خطوة مسائية، مع حماية شمسية في النهار.'),('هل أبدأ يوميًا؟','ابدئي بالتدرّج قبل زيادة التكرار حسب التحمل.')]),lang('Celimax The Vita-A Retinal Shot Tightening Booster','An evening step, introduced slowly.','A targeted retinal booster for the look of fine lines and uneven texture, used sparingly within an evening routine.',['Smoother-looking texture','Fine-line appearance care','Small targeted application'],'A focused evening booster','Spread a little over target areas, then add moisturiser.','For gradual retinoid routines, rather than stacking several exfoliating steps.',[('Introduce slowly','Use on alternate nights for the first two weeks as tolerated.'),('Apply sparingly','Keep a small amount away from eyes and lips.'),('Finish gently','Follow with moisturiser and wear daytime sunscreen.')],'Reduce use if irritation develops. Avoid retinoids during pregnancy or when trying to conceive.',['Retinal','A-Shot formulation'],[('Morning or evening?','Use in the evening, with sun protection the next day.'),('Daily from day one?','Increase frequency only after your skin adjusts.')]),[('https://celimax.us/products/the-vita-a-retinal-shot-tightening-booster','Celimax US — The Vita A Retinal Shot Tightening Booster')],research=['Official page states 0.1% retinal; no need to put strength in marketing copy.'])
add('TS0066',lang('ماسك بايو كولاجين ريل ديب من بايودانس','استراحة طويلة، وإحساس مرطّب.','ماسك هيدروجيل من جزأين يمنح البشرة ترطيبًا ولمسة ممتلئة المظهر خلال وقت عنايتكِ الهادئ.',['ترطيب للبشرة','مظهر أكثر امتلاءً','هيدروجيل يلتصق بالوجه'],'هيدروجيل يتحول تدريجيًا','تزداد شفافيته أثناء مدة الاستخدام؛ ليس قناعًا ورقيًا عاديًا.','لمن تفضّل جلسة ترطيب ممتدة بدل الماسكات السريعة.',[('حضّري بشرتكِ','ضعيه بعد التنظيف والتونر أو السيروم.'),('ثبّتي الجزأين','انزعي الأغشية ووزّعي القناع حول العينين والفم.'),('امنحيه وقته','اتركيه 3–4 ساعات أو حتى يصبح شفافًا، ثم أزيليه.')],'للاستخدام الواحد؛ أزيليه عند الانزعاج. عدد الماسكات يتبع الباقة المعروضة.', ['كولاجين متحلل','حمض هيالورونيك'],[('هل يُشطف بعده؟','اربتي برفق على البقايا وفق تعليمات العبوة.'),('هل هو قناع سريع؟','تعليمات الشركة تتضمن جلسة نهارية من 3–4 ساعات.')]),lang('Biodance Bio-Collagen Real Deep Mask','Make time for a hydrating pause.','A two-part hydrogel mask for comfortable hydration and a plumper-looking finish during an extended skincare break.',['Hydrating care','Plumper-looking finish','Close-fitting hydrogel'],'Hydrogel that gradually clears','The mask becomes more transparent during wear.','For an extended moisture session rather than a quick sheet mask.',[('Prepare','Apply after cleansing and toner or serum.'),('Position','Remove the films and align both pieces around eyes and mouth.'),('Allow time','Wear for 3–4 hours or until transparent, then remove.')],'Single use. Remove if uncomfortable; pack quantity follows the selected offer.',['Hydrolysed collagen','Hyaluronic acid'],[('Rinse afterwards?','Gently pat remaining essence as directed on the pack.'),('A quick mask?','The brand describes a 3–4 hour daytime session.')]),[('https://biodance.com/products/biodance-bio-collagen-real-deep-mask','Biodance — Bio Collagen-Real Deep Mask')])
add('TS0068',lang('باتشات العين PDRN وريتينال من أبيب','دقائق لعناية منطقة العين.','باتشات جلّية للعناية بمظهر التعب حول العينين، تجمع الترطيب مع الريتينال وPDRN.',['ترطيب تحت العين','مظهر أكثر انتعاشًا','ملمس هلامي مريح'],'جل مرن قريب من البشرة','باتشات ذات سطح يساعدها على الثبات أثناء الجلسة.','لعناية خارجية بمنطقة تحت العين؛ لا توضع داخل العين أو على الجفن المتحرك.',[('اختاري زوجًا','استخدمي الملعقة النظيفة لرفع الباتشات.'),('ضعي برفق','ثبّتيها تحت العين دون ملامسة خط الرموش.'),('انتظري وأزيلي','اتركيها 10–15 دقيقة، ثم أزيليها واربتي على البقايا.')],'تحتوي ريتينال؛ تجنبيها أثناء الحمل والتخطيط له، وأوقفيها عند التهيج.', ['PDRN','ريتينال','كافيين'],[('هل أنام بها؟','اتبعي جلسة 10–15 دقيقة المبيّنة في إرشادات الشركة.'),('هل تلامس العين؟','توضع على الجلد الخارجي تحت العين فقط.')]),lang('Abib PDRN Retinal Eye Patch Glow Jelly','A few minutes for your eye contour.','Jelly patches combine moisture with retinal and PDRN for a refreshed-looking under-eye area.',['Under-eye hydration','Refreshed appearance','Comfortable jelly feel'],'Flexible close-fitting jelly','A textured surface helps the patches stay in place.','For external under-eye skin, away from eyes and moving eyelids.',[('Lift carefully','Use the clean spatula to take out a pair.'),('Position gently','Place beneath the eyes without touching the lash line.'),('Remove','Leave for 10–15 minutes, then pat in remaining essence.')],'Contains retinal. Avoid during pregnancy or when trying to conceive; stop if irritated.',['PDRN','Retinal','Caffeine'],[('Sleep in them?','Follow the brand’s 10–15 minute application guidance.'),('Touch the eyes?','Apply only to external under-eye skin.')]),[('https://en.abib.com/products/pdrn-retinal-eye-patch-glow-jelly','Abib — PDRN retinal eye patch Glow jelly')])
add('TS0072',lang('ماسك هولي بازل الفقاعي من بي كالم','من قوام الماسك إلى فقاعات التنظيف.','ماسك يُشطف، يتحول إلى فقاعات لطيفة كخطوة تنظيف إضافية عندما تحتاج بشرتكِ ذلك.',['تنظيف سطح البشرة','تجربة فقاعية','ملمس أنعم بعد الشطف'],'فقاعات فوق طبقة الماسك','يتطور القوام على البشرة قبل تدليك لطيف وشطف كامل.','لمن تريد ماسك تنظيف يُشطف، مع تقليل الاستخدام إذا كانت البشرة سريعة التهيج.',[('وزّعي طبقة','ضعيه على بشرة جافة بعيدًا عن العينين.'),('دعي الفقاعات تتكون','انتظري المدة المحددة على العبوة ثم دلّكي بلطف.'),('اشطفي ورطّبي','أزيليه بالماء الفاتر وأكملي بمرطب.')],'لا تفركي بقوة أو تستخدميه على جلد متضرر. أغلقي الغطاء جيدًا.', ['هولي بازل','قوام فقاعي يُشطف'],[('هل يبقى على الوجه؟','يُشطف بالكامل؛ ليس كريمًا يُترك على البشرة.'),('هل أترك العبوة مفتوحة؟','أعيدي إغلاقها بإحكام بعد أخذ الكمية.')]),lang('P.CALM Holy Basil Bubble Deep Mask','A cleansing mask that turns to bubbles.','A rinse-off bubbling mask for an additional surface-cleansing step when your skin needs one.',['Surface cleansing','Bubbling application','Softer skin feel'],'From mask to foam','Allow bubbles to form before gentle massage and rinsing.','For a rinse-off cleansing session, used less often if skin feels reactive.',[('Spread','Apply to dry skin, avoiding the eyes.'),('Let it bubble','Wait for the pack’s stated time and massage gently.'),('Rinse','Remove thoroughly with lukewarm water, then moisturise.')],'Avoid strong rubbing and damaged skin. Close the lid firmly after use.',['Holy basil','Rinse-off bubble texture'],[('Leave it on?','Rinse it away completely; it is not a moisturiser.'),('Leave the jar open?','Close tightly after taking out your portion.')]),[('https://www.pcalm.co.kr/product/detail.html?product_no=1216','P.CALM Korea — Holy Basil Bubble Deep Mask'),('https://pcalm.us/products/p-calm-holy-basil-sparking-bubble-13-mask','P.CALM US indexed product')],'limited',['Primary Korean page retrieved; image-heavy directions not fully readable. US indexed page now404. Exact timing deferred to pack rather than copying retailer timing.'])
