add('TS0085',lang('واقي سنتيلا هيالو سيكا ووتر فيت من سكين1004','واقي شمس بإحساس السيروم.','حماية نهارية بقوام خفيف مرطّب؛ سنتيلا وهيالورونيك لإحساس مريح ضمن روتين الصباح.',['حماية من الشمس','ملمس خفيف','ترطيب مريح'],'من قوام السيروم إلى تغطية متساوية','افرديه جيدًا على الوجه والرقبة دون الاكتفاء بطبقة رقيقة جدًا.','لمن تفضّل واقيًا مرطّبًا خفيفًا؛ اتبعي درجة الحماية وتركيبة العبوة المتاحة.',[('آخر خطوة عناية','ضعيه بعد المرطب وقبل المكياج.'),('تغطية كافية','وزّعي الكمية المبيّنة على العبوة بالتساوي.'),('جدّدي عند الحاجة','اتبعي تعليمات إعادة التطبيق أثناء النهار.')],'النسخ الإقليمية قد تختلف؛ لا نفترض مرشحات النسخة الأمريكية للعبوة الكورية.', ['سنتيلا','حمض هيالورونيك'],[('هل هو سيروم فقط؟','هو واقي شمس رغم قوامه الشبيه بالسيروم.'),('هل تختلف النسخ؟','نعم؛ تفاصيل الحماية والمكونات المرجع فيها عبوتكِ.')]),lang('SKIN1004 Hyalu-Cica Water-Fit Sun Serum','Sun protection with a serum-like feel.','A light hydrating sunscreen with centella and hyaluronic care for a comfortable morning finish.',['Daytime UV protection','Light serum-like texture','Hydrating comfort'],'Spread into an even layer','Cover face and neck adequately rather than using a very thin film.','For a light hydrating sunscreen; follow your specific pack’s rating and formula.',[('Last skincare step','Apply after moisturiser, before makeup.'),('Cover adequately','Spread the labelled amount evenly.'),('Renew','Follow the pack’s daytime reapplication directions.')],'Regional versions differ; US filters are not assumed for a Korean-labelled tube.',['Centella','Hyaluronic acid'],[('Only a serum?','It is sunscreen despite the serum-like feel.'),('Do versions differ?','Yes. Your pack controls protection and ingredient details.')]),[('https://www.skin1004.com/products/hyalu-cica-water-fit-sun-serum-uv?variant=51261874995446','SKIN1004 — Hyalu-Cica Water-Fit Sun Serum UV'),('https://www.skin1004.com/pages/collection-series','SKIN1004 — Collection Series')],'family',['Current US product is reformulated SPF50; existing Korean catalog hero retained. No filters/PA/US drug claims transferred.'])
add('TS0087',lang('زيت التنظيف الخفيف بالسنتيلا من سكين1004','ابدئي ببشرة جافة، وانتهي بشطف مريح.','زيت خفيف لإذابة المكياج وواقي الشمس، يتحول مع الماء إلى مستحلب يسهل شطفه.',['إزالة المكياج وواقي الشمس','ملمس زيتي خفيف','يتحول إلى مستحلب'],'زيت يتحول إلى حليب','إضافة الماء والتدليك اللطيف جزء أساسي من شطفه.','لمن تريد خطوة تنظيف زيتي قبل الغسول المائي عند الحاجة.',[('بيدين جافتين','دلّكي كمية مناسبة على وجه جاف.'),('أضيفي الماء','استمري بالتدليك حتى يصبح مستحلبًا حليبيًا.'),('اشطفي بالكامل','استخدمي ماء فاترًا وأتبعيه بالغسول عند الحاجة.')],'تحتوي التركيبة زيوتًا عطرية؛ اختبريها عند الحساسية وتجنبي دخولها العين.', ['سنتيلا','زيت الجوجوبا','زيت دوار الشمس'],[('على بشرة مبللة؟','ابدئي على وجه ويدين جافتين.'),('هل يُترك كزيت ترطيب؟','لا؛ هو منتج تنظيف يجب شطفه.')]),lang('SKIN1004 Centella Light Cleansing Oil','Start dry, then rinse comfortably.','A light cleansing oil dissolves makeup and sunscreen, then emulsifies with water for thorough rinsing.',['Makeup and SPF removal','Light oil texture','Milky emulsification'],'Oil that turns milky','Adding water is an important part of removal.','For an oil-cleansing step before a water-based cleanser when needed.',[('Start dry','Massage an appropriate amount onto dry skin with dry hands.'),('Emulsify','Add water and massage until milky.'),('Rinse','Rinse completely with lukewarm water.')],'Contains aromatic botanical oils; patch test if sensitive and avoid eye contact.',['Centella','Jojoba oil','Sunflower oil'],[('On wet skin?','Start with a dry face and hands.'),('Leave on as face oil?','No; this cleanser must be rinsed away.')]),[('https://www.skin1004.com/collections/cleanser/products/skin1004-madagascar-centella-light-cleansing-oil','SKIN1004 — Centella Light Cleansing Oil')])
add('TS0102',lang('جل كريم بورمايزنغ الخفيف من سكين1004','ترطيب منعش بلمسة جل.','جل كريم خفيف يضم ألوفيرا ونياسيناميد، لمن تفضّل ترطيبًا بإحساس منعش ومظهر ناعم.',['ترطيب خفيف','إحساس منعش','عناية بمظهر الملمس'],'جل خفيف سهل الفرد','يمتد على البشرة ويترك إحساسًا مرطّبًا دون قوام كريمي ثقيل.','لمن تفضّل الجل في خطوة الترطيب، خصوصًا عند تجنب الكريمات الغنية.',[('بعد السيروم','خذي مقدارًا يناسب وجهكِ.'),('افردي بلطف','وزّعيه بالتساوي على الجلد.'),('ثبّتي الترطيب','اربتي براحتيكِ وأضيفي واقي الشمس نهارًا.')],'لا يغيّر حجم المسام تشريحيًا؛ المقصود العناية بمظهرها وملمس البشرة.', ['ألوفيرا','نياسيناميد','سنتيلا'],[('هل هو غسول؟','هو مرطب يُترك على البشرة.'),('متى أضعه؟','في نهاية العناية وقبل الواقي صباحًا.')]),lang('SKIN1004 Poremizing Light Gel Cream','A refreshing gel moisturiser.','A lightweight aloe-and-niacinamide gel cream for a hydrated feel and smoother-looking skin.',['Light moisture','Refreshing feel','Texture appearance care'],'Easy-spreading gel','A lighter-feeling finish than a rich cream.','For those who prefer gel moisturisers over heavy creams.',[('After serum','Take an appropriate amount.'),('Smooth','Spread gently over the face.'),('Finish','Pat with your palms; add daytime sunscreen.')],'Pore care refers to appearance, not permanently changing pore anatomy.',['Aloe','Niacinamide','Centella'],[('A cleanser?','No; leave this moisturiser on.'),('When in the routine?','At the moisturising step, before morning sunscreen.')]),[('https://www.skin1004.com/products/poremizing-light-gel-cream','SKIN1004 — Poremizing Light Gel Cream')])
add('TS0103',lang('كريم سنتيلا المهدّئ من سكين1004','راحة الترطيب بقوام جل كريمي.','مرطب خفيف بالسنتيلا والتريهالوز ومكونات داعمة لحاجز البشرة، لإنهاء العناية بإحساس مريح.',['ترطيب يومي','دعم حاجز البشرة','إحساس غير لزج'],'جل كريمي بلون طبيعي خفيف','ينساب على البشرة ويُربّت عليه ليمتص.','للبشرة العادية أو التي تفضّل ترطيبًا خفيفًا؛ اختبريه إذا كانت شديدة الحساسية.',[('بعد العناية','خذي كمية مناسبة بعد السيروم.'),('وزّعي','مدّي المرطب برفق على الوجه.'),('اربتي','اتركيه على البشرة وأتبعيه بالواقي صباحًا.')],'أوقفيه عند التهيج؛ اسم Soothing Cream لا يعني علاج الالتهابات الجلدية.', ['سنتيلا','تريهالوز','سيراميد NP'],[('هل يُشطف؟','يبقى على البشرة كمرطب.'),('هل قوامه غني جدًا؟','تصفه الشركة بجل كريمي خفيف غير لزج.')]),lang('SKIN1004 Centella Soothing Cream','Comfortable moisture in a gel cream.','A centella-and-trehalose moisturiser with barrier-supporting ingredients for a comfortable end to skincare.',['Daily hydration','Barrier support','Non-sticky feel'],'Light naturally tinted gel cream','Smooth over skin, then gently pat.','For normal skin or anyone preferring a light moisturiser; patch test reactive skin.',[('After skincare','Take an appropriate amount after serum.'),('Spread','Smooth gently over the face.'),('Pat','Leave on and finish with morning sunscreen.')],'Stop if irritated; soothing skincare is not treatment for skin disease.',['Centella','Trehalose','Ceramide NP'],[('Rinse?','Leave it on as your moisturiser.'),('Very rich?','The brand describes a light, non-sticky gel cream.')]),[('https://www.skin1004.com/collections/cream/products/skin1004-madagascar-centella-soothing-cream','SKIN1004 — Centella Soothing Cream')])
