add('TS0116',lang('سيروم الرموش ماي لاش من إيتود','عناية خفيفة للرموش النظيفة.','سيروم يومي ببانثينول وبيوتين للعناية بمظهر الرموش وملمسها، بفرشاة سهلة التحكم.',['ترطيب الرموش','مظهر رموش معتنى بها','تطبيق بالفرشاة'],'سيروم شفاف وخفيف','يُستخدم بكمية قليلة دون إغراق الفرشاة.','لمن تبحث عن عناية تجميلية للرموش؛ لا نقدمه كدواء لإنباتها.',[('نظّفي الرموش','أزيلي المكياج وجففي المنطقة.'),('مشّطي برفق','مرري كمية قليلة على الرموش دون لمس العين.'),('اتركيه يجف','أغلقي العبوة وحافظي على نظافة الفرشاة.')],'لا تضعيه داخل العين أو على جلد متهيج؛ أوقفيه إذا سبب حرقة.', ['بانثينول','بيوتين'],[('هل هو ماسكارا ملونة؟','هو عناية للرموش، لا منتج تلوين.'),('هل يضمن تطويل الرموش؟','لا نعد بإنبات أو طول محدد.')]),lang('ETUDE My Lash Serum','Light care for clean lashes.','A panthenol-and-biotin lash serum for conditioning and a cared-for appearance with a controlled brush application.',['Lash conditioning','Cared-for appearance','Brush application'],'A light clear serum','Use a little without overloading the brush.','For cosmetic lash care, not a medicine for regrowth.',[('Clean','Remove makeup and dry the lash area.'),('Brush gently','Apply a little to lashes without touching the eye.'),('Let dry','Close the tube and keep the brush clean.')],'Do not apply inside eyes or on irritated skin; stop if burning occurs.',['Panthenol','Biotin'],[('Coloured mascara?','No; this is a lash-care product.'),('Guaranteed longer lashes?','No specific growth or length is promised.')]),[('https://int.etude.com/shop/category/eye/my-lash-serum-9g/','ETUDE Global — My Lash Serum')])
add('TS0117',lang('سيروم فيتامين برايتنينغ آند بالانسنغ من جوميسو','إشراقة يومية في طبقة خفيفة.','سيروم خفيف بمستخلص النبق البحري ونياسيناميد، للعناية بالبهتان وإضافة ترطيب قبل الكريم.',['مظهر أكثر إشراقًا','ترطيب خفيف','قوام سهل الطبقات'],'سيروم سريع التوزيع','يوزّع بعد التونر ويُترك قبل المرطب.','لروتين صباحي أو مسائي يحتاج خطوة خفيفة للعناية بمظهر البهتان.',[('بعد التنظيف','ضعي كمية مناسبة بعد التونر.'),('وزّعي بالتساوي','اربتي على الوجه برفق.'),('أكملي الروتين','أتبعيه بالمرطب، ثم الواقي صباحًا.')],'مستخلص Vitamin Tree ليس تركيزًا مماثلًا لفيتامين C النقي؛ راجعي العبوة للحساسية.', ['مستخلص النبق البحري','نياسيناميد','هيالورونات الصوديوم'],[('صباحًا أم مساءً؟','تذكر الشركة الاستخدام في الروتينين.'),('هل هو فيتامين C نقي؟','تُبنى تركيبته على مستخلص نباتي ومكونات أخرى، لا نفترض تركيزًا نقيًا.')]),lang('Jumiso All Day Vitamin Brightening & Balancing Serum','Everyday radiance in a light layer.','A light sea-buckthorn-and-niacinamide serum for dullness care and hydration before cream.',['Brighter-looking skin','Light hydration','Easy layering'],'A light spreading serum','Apply after toner and leave on before moisturiser.','For a morning or evening routine focused on dull-looking skin.',[('Prepare','Apply an appropriate amount after cleansing and toner.'),('Spread','Distribute evenly and gently pat.'),('Finish','Add moisturiser and morning sunscreen.')],'Vitamin-tree extract is not equivalent to a pure vitamin C percentage. Check pack allergens.',['Sea-buckthorn extract','Niacinamide','Sodium hyaluronate'],[('Morning or night?','The brand describes both morning and evening use.'),('Pure vitamin C?','The formula uses plant extract and other ingredients; no pure-C strength is assumed.')]),[('https://jumiso.us/products/all-day-vitamin-brightening-balancing-serum','Jumiso US — All Day Vitamin Brightening & Balancing Serum')])
