add('TS0206',lang('كريم العين ريتينول إنتنس من سوم باي مي','كمية صغيرة، وعناية مسائية دقيقة.','كريم ريتينول مخصص لمحيط العين، للعناية بمظهر الخطوط والبهتان ضمن روتين متدرّج.',['عناية بمظهر الخطوط','ترطيب محيط العين','تطبيق مسائي محدد'],'طبقة كريم رقيقة','اربتي على المنطقة الخارجية دون فرك أو اقتراب من العين.','لمن تريد ريتينويدًا مخصصًا للعين، مع الالتزام بالتدرّج.',[('نهاية عناية المساء','خذي كمية صغيرة بعد تنظيف البشرة والعناية.'),('اربتي حول المحيط','ضعيه بعيدًا عن خط الرموش والجفن المتحرك.'),('راقبي التحمل','اتبعي تكرار العبوة واستخدمي واقيًا نهارًا.')],'يحتوي ريتينول؛ يُتجنب أثناء الحمل والتخطيط له. لا تضعيه داخل العين.', ['ريتينول','نياسيناميد','بانثينول'],[('هل هو السيروم الوجهي؟','لا؛ هذا كريم العين المخصص.'),('هل أبدأ بكمية كبيرة؟','ابدئي بكمية صغيرة وتكرار متدرج.')]),lang('SOME BY MI Retinol Intense Advanced Triple Action Eye Cream','A small, careful evening application.','A dedicated retinol eye cream for fine-line and dullness appearance care within a gradual routine.',['Fine-line appearance care','Eye-contour moisture','Focused evening use'],'A thin cream layer','Pat the external contour without rubbing or touching eyes.','For gradually introducing an eye-specific retinoid.',[('Finish evening skincare','Take a small amount after cleansing and skincare.'),('Pat around the contour','Keep clear of lashes and moving eyelids.'),('Monitor','Follow labelled frequency and use daytime sunscreen.')],'Contains retinol. Avoid during pregnancy or when trying to conceive; keep out of eyes.',['Retinol','Niacinamide','Panthenol'],[('The facial serum?','No; this is the dedicated eye cream.'),('Start generously?','Begin with a small amount and gradual frequency.')]),[('https://somebymi.com/product/detail.html?product_no=265','SOME BY MI Korea — Retinol Intense Advanced Triple Action Eye Cream')],research=['Primary Korean product text specifies evening use as final skincare step and lists retinol0.1%; no numeric claim needed publicly.'])
add('TS0226',lang('أمبول الذهب والببتيدات برايم من فارم ستاي','طبقة ترطيب بلمسة ذهبية.','أمبول بقوام جل مرطّب ومكونات ببتيدية، للعناية بمظهر النعومة والإشراقة قبل الكريم.',['ترطيب للبشرة','مظهر أكثر نعومة','عناية بالبهتان'],'جل أمبول بلمعة ذهبية','كمية مناسبة تُفرد وتُربّت حتى تمتص.','لمن تفضّل أمبول ترطيب بقوام جل؛ اسم 24K لا يعني نسبة ذهب في التركيبة.',[('بعد التونر','خذي كمية مناسبة بأداة أو يد نظيفة.'),('وزّعي بخفة','مدّي الأمبول على الوجه بعيدًا عن العينين.'),('اربتي وأكملي','اتركيه يمتص ثم أضيفي الكريم.')],'راجعي قائمة العبوة للحساسية، خاصة منتجات النحل إذا ظهرت ضمنها.', ['ببتيدات','نياسيناميد','مستخلص غذاء ملكات النحل'],[('هل يغني عن الكريم؟','أكملي بمرطب إذا احتاجت بشرتكِ.'),('هل 24K تعني تركيزًا؟','لا؛ لا نستنتج منها نسبة ذهب في المنتج.')]),lang('Farmstay 24K Gold & Peptide Solution Prime Ampoule','A moisturising layer with a golden touch.','A hydrating gel ampoule with peptide care for a smoother, more radiant-looking finish before cream.',['Skin hydration','Smoother appearance','Dullness care'],'A gold-flecked gel ampoule','Spread an appropriate amount and pat to absorb.','For a gel-ampoule preference; 24K is not a gold concentration claim.',[('After toner','Take an appropriate amount with a clean tool or hand.'),('Spread lightly','Apply to the face, avoiding eyes.'),('Pat and finish','Let absorb, then add cream.')],'Check pack allergens, including bee-derived ingredients where listed.',['Peptides','Niacinamide','Royal jelly extract'],[('Replace cream?','Add moisturiser if your skin needs it.'),('Does24K mean concentration?','No percentage of gold is inferred from the name.')]),[('https://en.fscos.com/product/farmstay-24k-gold-peptide-solution-prime-ampoule/132/','Farmstay — 24K Gold & Peptide Solution Prime Ampoule')],research=['Manufacturer page confirms niacinamide and royal jelly; catalog size remains unchanged because not clearly recorded. No claims that gold creates medical or exceptional benefits.'])
add('TS0331',lang('أمبول الكولاجين البحري من إليزافيكا','قطرات لعناية الملمس والترطيب.','أمبول بكولاجين متحلل ومكونات مرطّبة، يضيف طبقة عناية خفيفة قبل الكريم.',['ترطيب للملمس','مظهر أنعم','تطبيق بقطرات قليلة'],'قوام أمبول قابل للتوزيع','قطرتان أو ثلاث تُربّت على المناطق المطلوبة.','لمن تريد إضافة أمبول ترطيب؛ لا يُقدم كتعويض للكولاجين داخل الجلد.',[('خذي قطرات قليلة','استخدمي 2–3 قطرات بعد التنظيف والتونر.'),('وزّعي','مدّيه على المناطق الخشنة أو الباهتة بعيدًا عن العينين.'),('اربتي','اتركيه يمتص وأكملي بالمرطب.')],'يتضمن عطرًا ومكونات بحرية؛ راجعي الملصق عند الحساسية.', ['كولاجين متحلل','غليسرين','ألانتوين'],[('هل هو95% كولاجين؟','لا نعرض هذه النسبة؛ المرجع قائمة العبوة.'),('هل يوضع حول العين؟','تطلب تعليمات الشركة تجنب منطقة العين.')]),lang('Elizavecca Witch Piggy Hell-Pore Marine Collagen Ample','A few drops for moisture and texture care.','A hydrolysed-collagen ampoule adds a hydrating layer before cream for a softer skin feel.',['Skin-feel hydration','Smoother appearance','Few-drop application'],'An easy-spreading ampoule','Pat two or three drops onto target areas.','For an extra moisture step, not replenishing collagen inside the skin.',[('Take a few drops','Use 2–3 drops after cleansing and toner.'),('Spread','Apply to rough or dull-looking areas, clear of eyes.'),('Pat','Let absorb, then moisturise.')],'Contains fragrance and marine-derived ingredients; check pack allergens.',['Hydrolysed collagen','Glycerin','Allantoin'],[('Ninety-five percent collagen?','That percentage is not claimed; refer to your pack.'),('Around the eyes?','The brand instructs avoiding the eye area.')]),[('https://elizavecca.com/goods/goods_view.php?goodsNo=955','Elizavecca — Witch Piggy Hell-Pore Marine Collagen Ample')],research=['Official current ingredient list states hydrolysed collagen9,500ppm, not95%. Retailer95% claims rejected. Product photo/version controls exact formulation.'])
